contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount1, uint amount2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1) + (amount2)); require(amount1 <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000);
        require(address(this).balance >= amount1 + amount2, "insufficient balance");

        uint initialBalance = address(c).balance;

        c.deposit{value: amount1}(); if (__ESBMC_reverted()) return;
        uint afterFirstDeposit = address(c).balance;
        c.deposit{value: amount2}(); if (__ESBMC_reverted()) return;
        uint afterSecondDeposit = address(c).balance;

        bool reverted1;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted1 = true;
        } else {
            reverted1 = false;
        }

        bool reverted2;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted2 = true;
        } else {
            reverted2 = false;
        }

        assert(
            afterFirstDeposit == initialBalance + amount1 &&
            afterSecondDeposit == afterFirstDeposit + amount2 &&
            address(c).balance == initialBalance
        );
    }

    receive() external payable {}
}

